#include <lodepng.h>
#include <math.h>

#define INPUT_DIM 28
#define HIDDEN_DIM 16
#define NUM_CLASSES 10

// Load weights from JSON
tensor_t load_weights(const char* filename) {
    FILE* f = fopen(filename, "r");
    if (!f) {
        printf("Error: cannot open %s\n", filename);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* data = malloc(len);
    fread(data, 1, len, f);
    fclose(f);
    cJSON* root = cJSON_Parse(data);
    free(data);

    tensor_t weights = tensor_create(HIDDEN_DIM * HIDDEN_DIM + HIDDEN_DIM * INPUT_DIM + HIDDEN_DIM + NUM_CLASSES * HIDDEN_DIM);

    // input_layer.weight
    cJSON* key = cJSON_GetObjectItemCaseSensitive(root, "input_layer.weight");
    if (!key || !key->value.array) {
        printf("Missing input_layer.weight\n");
        exit(1);
    }
    for (int i = 0; i < HIDDEN_DIM * INPUT_DIM; i++) {
        weights.data[i] = key->value.array[i] / 255.0; // normalize
    }

    // input_layer.bias
    key = cJSON_GetObjectItemCaseSensitive(root, "input_layer.bias");
    for (int i = 0; i < HIDDEN_DIM; i++) {
        weights.data[HIDDEN_DIM * INPUT_DIM + i] = key->value.array[i] / 255.0;
    }

    // hidden_layer.weight
    key = cJSON_GetObjectItemCaseSensitive(root, "hidden_layer.weight");
    for (int i = 0; i < HIDDEN_DIM * HIDDEN_DIM; i++) {
        weights.data[HIDDEN_DIM * INPUT_DIM + HIDDEN_DIM + i] = key->value.array[i] / 255.0;
    }

    // hidden_layer.bias
    key = cJSON_GetObjectItemCaseSensitive(root, "hidden_layer.bias");
    for (int i = 0; i < HIDDEN_DIM; i++) {
        weights.data[HIDDEN_DIM * INPUT_DIM + HIDDEN_DIM + HIDDEN_DIM + i] = key->value.array[i] / 255.0;
    }

    // output_layer.weight
    key = cJSON_GetObjectItemCaseSensitive(root, "output_layer.weight");
    for (int i = 0; i < NUM_CLASSES * HIDDEN_DIM; i++) {
        weights.data[HIDDEN_DIM * INPUT_DIM + HIDDEN_DIM + HIDDEN_DIM + HIDDEN_DIM + i] = key->value.array[i] / 255.0;
    }

    // output_layer.bias
    key = cJSON_GetObjectItemCaseSensitive(root, "output_layer.bias");
    for (int i = 0; i < NUM_CLASSES; i++) {
        weights.data[HIDDEN_DIM * INPUT_DIM + HIDDEN_DIM + HIDDEN_DIM + HIDDEN_DIM + HIDDEN_DIM + i] = key->value.array[i] / 255.0;
    }

    return weights;
}

// Load image tensor from PNG
tensor_t load_image(const char* filename) {
